def android6_cases(suite):
    source = DEMO_CASES if suite == 'demo' else (*STORAGE_CASES, *UI_CASES)
    by_name = {case[0]: case for case in source}
    if len(by_name) != len(source):
        raise ValueError('Ambiguous name in the Android 6 offline allowlist')
    cases = tuple(by_name[name] for name in ANDROID6_CASE_NAMES[suite])
    if suite == 'demo':
        return (*cases, NORMALIZATION_CASE,
                ('android6-calendar', 'Android6PresentationUiTest#arabicCalendarPreservesTypedEarlyDatesAndRoundTripsLeapDay', False),
                ('android6-timezone', 'Android6PresentationUiTest#timezoneSearchAcceptsArabicCityAndTechnicalId', False))
    return (*cases, ANDROID6_NETWORK_CASE, PIN_BOUNDARY_CASE)


def select_cases(suite, methods=''):
    """Exact allowlist only; optional retry selects failed/unexecuted methods across batches."""
    all_cases = DEMO_CASES if suite == 'demo' else tuple(case for batch in STANDARD_BATCHES.values() for case in batch)
    cases = DEMO_CASES if suite == 'demo' else STANDARD_BATCHES[suite]
    if not methods:
        return cases
    requested = methods.split(',')
    if any(not method or method != method.strip() for method in requested) or len(set(requested)) != len(requested):
        raise ValueError('Use unique exact Class#method selectors separated by commas without spaces')
    if not set(requested) <= {case[1] for case in all_cases}:
        raise ValueError('Retry selector is not in the offline allowlist for this flavor')
    return tuple(case for case in cases if case[1] in requested)


def adb(*args, timeout=30, check=True):
    return subprocess.run(['adb', '-s', SERIAL, *args], capture_output=True, timeout=timeout, check=check)


def process_ids(name, api):
    if api == 23:
        return legacy_process_ids(adb('shell', 'ps').stdout.decode(), name)
    return adb('shell', 'pidof', name, check=False).stdout.decode().split()


def verify_android6_avd(api):
    avd = adb('emu', 'avd', 'name').stdout.decode().splitlines()[:1]
    if (avd != ['aqaqeer-android6']
            or adb('shell', 'getprop', 'ro.kernel.qemu').stdout.strip() != b'1'
            or adb('shell', 'getprop', 'ro.build.version.sdk').stdout.strip() != str(api).encode()):
        raise RuntimeError(f'Expected the named, owned API {api} AVD and owner user')
    owner = (legacy_single_owner(adb('shell', 'pm', 'list', 'users').stdout.decode()) if api == 23
             else adb('shell', 'am', 'get-current-user').stdout.strip() == b'0')
    if not owner:
        raise RuntimeError('Expected owner user on the Android 6 compatibility AVD')


def verify_android6_installations(api, installations):
    verify_android6_avd(api)
    for package, owned in installations.items():
        identity, _ = installation_identity(package, observation='android6-phase')
        if identity != owned:
            raise RuntimeError('Android 6 phase no longer owns its installation')


def pin_delay_boundary(command, installations):
    owner = uuid.uuid4().hex
    results = []
    receipt = {}
    for phase in ('arm', 'restart', 'reboot'):
        verify_android6_installations(23, installations)
        if phase == 'restart':
            adb('shell', 'am', 'force-stop', PACKAGE)
            if process_ids(PACKAGE, 23):
                raise RuntimeError('PIN restart prerequisite failed: the app process is still running')
            receipt['processAbsentBeforeRestart'] = True
        elif phase == 'reboot':
            old_boot = adb('shell', 'cat', '/proc/sys/kernel/random/boot_id').stdout.strip()
            if not re.fullmatch(rb'[a-f0-9-]{36}', old_boot):
                raise RuntimeError('Could not establish boot identity before the PIN reboot')
            adb('reboot')
            adb('wait-for-device', timeout=90)
            deadline = time.monotonic() + 90
            while True:
                ready = adb('shell', 'getprop', 'sys.boot_completed', check=False).stdout.strip()
                new_boot = adb('shell', 'cat', '/proc/sys/kernel/random/boot_id', check=False).stdout.strip()
                if ready == b'1' and new_boot != old_boot and re.fullmatch(rb'[a-f0-9-]{36}', new_boot):
                    break
                if time.monotonic() >= deadline:
                    raise RuntimeError('Owned Android 6 AVD did not complete a new boot')
                time.sleep(1)
            verify_android6_installations(23, installations)
            receipt.update(bootIdBefore=old_boot.decode(), bootIdAfter=new_boot.decode())
        phase_command = [*command[:-1], '-e', 'android6PinPhase', phase, '-e', 'android6PinOwner', owner, command[-1]]
        result = adb(*phase_command, timeout=120, check=False)
        passed = instrumentation_passed(result, PIN_BOUNDARY_CASE[1])
        (OUTPUT / f'android6-pin-{phase}.log').write_bytes(result.stdout + result.stderr)
        results.append({'phase': phase, 'passed': passed})
        (OUTPUT / 'android6-pin-boundary.json').write_text(json.dumps({**receipt, 'phases': results}, indent=2) + '\n')
        if not passed:
            return result
    return result


def exchange_backup(phase, api, installations, *, after):
    """Transfer only synthetic test backups between fresh AVDs in one runner job."""
    outgoing = phase in ('export', 'peer') if after else False
    incoming = phase in ('peer', 'return') if not after else False
    if not (outgoing or incoming):
        return None
    verify_android6_installations(api, installations)
    directory = Path(os.environ['RUNNER_TEMP']) / 'aqaqeer-android6-exchange'
    directory.mkdir(mode=0o700, exist_ok=True)
    if outgoing:
        remote = 'files/android6-exchange-out.aqbak'
        sample = adb('exec-out', 'run-as', PACKAGE, 'cat', remote).stdout
        if not 0 < len(sample) <= 1_048_576:
            raise RuntimeError('Missing or oversized Android 6 export fixture')
        with (directory / f'from-api{api}.aqbak').open('xb') as target:
            target.write(sample)
        adb('shell', 'run-as', PACKAGE, 'rm', remote)
    else:
        remote = 'files/android6-exchange-in.aqbak'
        source = directory / f'from-api{35 if api == 23 else 23}.aqbak'
        sample = source.read_bytes()
        if not 0 < len(sample) <= 1_048_576:
            raise RuntimeError('Missing or oversized Android 6 import fixture')
        adb('shell', 'run-as', PACKAGE, 'mkdir', '-p', 'files')
        absence = adb('exec-out', 'run-as', PACKAGE, 'sh', '-c', f'if [ ! -e {remote} ]; then printf absent; fi')
        if absence.stdout != b'absent':
            raise RuntimeError('Expected a fresh Android 6 fixture destination')
        subprocess.run(['adb', '-s', SERIAL, 'exec-in', 'run-as', PACKAGE, 'sh', '-c', f'cat > {remote}'],
                       input=sample, capture_output=True, timeout=30, check=True)
        if adb('exec-out', 'run-as', PACKAGE, 'cat', remote).stdout != sample:
            raise RuntimeError('Android 6 fixture transfer failed byte verification')
    return hashlib.sha256(sample).hexdigest()


def instrumentation_passed(result, method):
    transcript = result.stdout + result.stderr
    expected_class, expected_method = method.split('#')
    return (result.returncode == 0 and bool(re.search(rb'OK \(1 tests?\)', transcript))
            and b'INSTRUMENTATION_CODE: -1' in transcript
            and not re.search(rb'INSTRUMENTATION_STATUS_CODE: -(?:3|4)\b', transcript)
            and ('INSTRUMENTATION_STATUS: class=com.aqaqeer.app.' + expected_class).encode() in transcript
            and ('INSTRUMENTATION_STATUS: test=' + expected_method).encode() in transcript)


def reader_lifecycle(command, name, method, owned):
    phase = READER_LIFECYCLE_CASES[method]
    namespace = 'suite_' + uuid.uuid4().hex
    relative = f'no_backup/{namespace}/reader-lifecycle.txt'
    phase_log = OUTPUT / f'{name}-prepare.log'
    evidence_file = OUTPUT / f'{name}-lifecycle.json'
    receipt = {'mode': phase, 'profile': namespace, 'verifiedBoundary': False}
    evidence_file.write_text(json.dumps(receipt, indent=2) + '\n')

    def phase_command(value):
        return [*command[:-1], '-e', 'readerLifecyclePhase', value, '-e', 'readerLifecycleProfile', namespace, command[-1]]

    def checkpoint():
        result = adb('shell', 'run-as', PACKAGE, 'cat', relative, check=False)
        match = re.fullmatch(rb'([1-9][0-9]*) ([0-9a-f-]{36}) ([0-9]+)\s*', result.stdout)
        return match.groups() if result.returncode == 0 and match else None

    def verify_installation():
        if (adb('shell', 'getprop', 'ro.kernel.qemu').stdout.strip() != b'1'
                or adb('shell', 'am', 'get-current-user').stdout.strip() != b'0'):
            raise RuntimeError('Reader boundary requires the owned emulator and user 0.')
        identity, _ = installation_identity(PACKAGE, observation=f'{name}-boundary')
        if identity != owned:
            raise RuntimeError('Reader boundary no longer owns its installation.')

    if phase == 'kill':
        with phase_log.open('wb') as log:
            prepare = subprocess.Popen(['adb', '-s', SERIAL, *phase_command(phase)], stdout=log, stderr=subprocess.STDOUT)
            try:
                cutoff = time.monotonic() + 50
                ready = checkpoint()
                while ready is None and prepare.poll() is None and time.monotonic() < cutoff:
                    time.sleep(0.25)
                    ready = checkpoint()
                if ready is None or prepare.poll() is not None:
                    raise RuntimeError('Reader process-death fixture did not reach the admitted transport read.')
                pid, work_id, _ = (part.decode() for part in ready)
                verify_installation()
                running = adb('shell', 'pidof', PACKAGE).stdout.decode().split()
                uid = adb('shell', 'run-as', PACKAGE, 'id', '-u').stdout.decode().strip()
                if running != [pid] or uid != owned['userId']:
                    raise RuntimeError('Reader attempt does not belong to the expected PID and app UID.')
                adb('shell', 'run-as', PACKAGE, 'kill', '-9', pid)
                prepare_return = prepare.wait(timeout=20)
                running = adb('shell', 'pidof', PACKAGE, check=False).stdout.decode().split()
                if pid in running:
                    raise RuntimeError('The admitted Reader process is still running after SIGKILL.')
                receipt.update(pid=int(pid), uid=int(uid), workId=work_id, prepareExitCode=prepare_return)
            finally:
                if prepare.poll() is None:
                    prepare.kill()
                    prepare.wait(timeout=5)
    else:
        prepared = adb(*phase_command(phase), timeout=60, check=False)
        phase_log.write_bytes(prepared.stdout + prepared.stderr)
        ready = checkpoint()
        if not instrumentation_passed(prepared, method) or ready is None:
            raise RuntimeError('Reader reboot fixture did not persist an unfinished WorkManager request.')
        pid, work_id, not_before = (part.decode() for part in ready)
        verify_installation()
        boot_id = adb('shell', 'cat', '/proc/sys/kernel/random/boot_id').stdout.decode().strip()
        if not re.fullmatch(r'[a-f0-9-]{36}', boot_id):
            raise RuntimeError('Could not establish the owned AVD boot identity.')
        adb('reboot')
        adb('wait-for-device', timeout=90)
        cutoff = time.monotonic() + 90
        while True:
            complete = adb('shell', 'getprop', 'sys.boot_completed', check=False).stdout.strip() == b'1'
            new_boot_id = adb('shell', 'cat', '/proc/sys/kernel/random/boot_id', check=False).stdout.decode().strip()
            if complete and re.fullmatch(r'[a-f0-9-]{36}', new_boot_id) and new_boot_id != boot_id:
                break
            if time.monotonic() >= cutoff:
                raise RuntimeError('The owned AVD did not return with a new, completed boot.')
            time.sleep(1)
        verify_installation()
        receipt.update(pid=int(pid), workId=work_id, notBeforeMillis=int(not_before), bootIdBefore=boot_id, bootIdAfter=new_boot_id)

    receipt['verifiedBoundary'] = True
    evidence_file.write_text(json.dumps(receipt, indent=2) + '\n')
    return adb(*phase_command('verify'), timeout=215 if phase == 'reboot' else 75, check=False)


def capture_native_startups(name, api):
    adb('shell', 'am', 'force-stop', PACKAGE)
    if process_ids(PACKAGE, api):
        raise RuntimeError('The cold launch requires an absent app process.')
    component = f'{PACKAGE}/com.aqaqeer.app.MainActivity'
    cold_pid = None
    for mode in ('cold', 'warm'):
        remote = f'/sdcard/aqaqeer-launch-{uuid.uuid4().hex}.mp4'
        with (OUTPUT / f'{name}-{mode}-recorder.log').open('wb') as log:
            recorder = subprocess.Popen(['adb', '-s', SERIAL, 'shell', 'screenrecord', '--size', '360x640',
                                         '--bit-rate', '1000000', '--time-limit', '12', remote],
                                        stdout=log, stderr=subprocess.STDOUT)
            try:
                cutoff = time.monotonic() + 4
                while adb('shell', 'test', '-f', remote, check=False).returncode != 0:
                    if recorder.poll() is not None or time.monotonic() >= cutoff:
                        raise RuntimeError('Native startup recorder did not start.')
                    time.sleep(0.2)
                # FLAG_ACTIVITY_NEW_TASK | FLAG_ACTIVITY_CLEAR_TASK works across the selected SDKs.
                result = adb('shell', 'am', 'start', '-W', '-f', '0x10008000',
                             '-a', 'android.intent.action.MAIN', '-c', 'android.intent.category.LAUNCHER',
                             '-n', component, check=False)
                (OUTPUT / f'{name}-{mode}-launch.txt').write_bytes(result.stdout + result.stderr)
                if result.returncode != 0 or b'Status: ok' not in result.stdout:
                    raise RuntimeError(f'Native {mode} launch did not report success.')
                pids = process_ids(PACKAGE, api)
                if len(pids) != 1 or not pids[0].isdigit():
                    raise RuntimeError(f'Native {mode} launch has an ambiguous application process.')
                if mode == 'cold':
                    cold_pid = pids[0]
                elif pids[0] != cold_pid:
                    raise RuntimeError('The warm activity launch did not retain the cold launch PID.')
                if recorder.wait(timeout=20) != 0:
                    raise RuntimeError(f'Native {mode} launch recorder failed.')
                video = OUTPUT / f'{name}-{mode}.mp4'
                adb('pull', remote, str(video))
                with video.open('rb') as stream:
                    if stream.read(8)[4:] != b'ftyp':
                        raise RuntimeError(f'Native {mode} launch recording is invalid.')
                (OUTPUT / f'{name}-{mode}-pid.txt').write_text(pids[0] + '\n')
            finally:
                try:
                    # The guest recorder has a bounded limit even if capture or launch fails.
                    recorder.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    recorder.kill()
                    recorder.wait(timeout=5)
                adb('shell', 'rm', '-f', remote, check=False)


def installation_identity(package, observation='current'):
    details = adb('shell', 'dumpsys', 'package', package).stdout.decode(errors='replace')
    # Keep the raw response even when parsing fails; never relax ownership to proceed.
    (OUTPUT / f'{package}-{observation}-package-dump.txt').write_text(details)
    # Android 15 renamed the package's userId field to appId. Fresh AVDs use user 0.
    identifiers = set(re.findall(r'^\s*(?:userId|appId)=([0-9]+)[ \t]*\r?$', details, re.M))
    if len(identifiers) != 1 or int(next(iter(identifiers))) < 10000:
        raise RuntimeError(f'Missing or ambiguous application UID ownership evidence for {package}')
    identity = {'userId': next(iter(identifiers))}
    for field in ('codePath', 'firstInstallTime', 'lastUpdateTime'):
        values = {value.strip() for value in re.findall(r'^\s*' + field + r'=([^\r\n]+)', details, re.M)}
        if len(values) != 1 or not next(iter(values)):
            raise RuntimeError(f'Missing or ambiguous {field} ownership evidence for {package}')
        identity[field] = next(iter(values))
    if not identity['codePath'].startswith('/data/app/'):
        raise RuntimeError(f'Unexpected installed code path for {package}')
    return identity, details


def require_absent(package):
    probe = adb('shell', 'pm', 'path', package, check=False)
    if probe.returncode not in (0, 1) or probe.stdout.strip() or probe.stderr.strip():
        raise RuntimeError(f'Package must be absent on the fresh AVD: {package}')


def save_results(suite, cases, results, capture_errors):
    finished = {item['case'] for item in results}
    payload = {'suite': suite, 'selected': len(cases), 'completedInvocations': len(results),
               'notExecuted': [method for name, method, _ in cases if name not in finished],
               'cases': results, 'captureErrors': capture_errors}
    temporary = OUTPUT / 'results.json.tmp'
    temporary.write_text(json.dumps(payload, indent=2) + '\n')
    temporary.replace(OUTPUT / 'results.json')


def main():
    global OUTPUT, PACKAGE
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--suite', choices=('demo', 'standard', 'storage', 'sharing', 'ui'), default='demo')
    parser.add_argument('--api23', action='store_true', help='Select the focused offline Android 6 profile')
    parser.add_argument('--android6-exchange', choices=('none', 'export', 'peer', 'return'), default='none')
    parser.add_argument('--selection-only', action='store_true', help='Validate selectors and emit has_checks without Android tooling')
    args = parser.parse_args()
    if args.api23 and args.suite not in ANDROID6_CASE_NAMES:
        parser.error('--api23 requires the demo or standard suite')
    phase = args.android6_exchange
    if phase != 'none' and (args.suite != 'standard' or args.api23 != (phase == 'export')):
        parser.error('Backup exchange requires Standard, with the Android 6 profile for its first phase only')
    if phase in ('peer', 'return'):
        OUTPUT /= f'exchange-{phase}'
        cases = (NORMALIZATION_CASE, EXCHANGE_CASE) if phase == 'peer' else (EXCHANGE_CASE,)
    else:
        cases = android6_cases(args.suite) if args.api23 else select_cases(
            args.suite, os.environ.get('CI_DEMO_RETRY_METHODS' if args.suite == 'demo' else 'CI_RETRY_METHODS', ''))
        if phase == 'export':
            cases = (*cases, EXCHANGE_CASE)
    if args.selection_only:
        with Path(os.environ['GITHUB_OUTPUT']).open('a') as output:
            output.write('has_checks=' + ('true' if cases else 'false') + '\n')
        if not cases:
            OUTPUT.mkdir(parents=True, exist_ok=True)
            save_results(args.suite, cases, [], [])
        print(f'Selected {len(cases)} checks for {args.suite}; no Android tooling used.')
        return
    flavor = 'demo' if args.suite == 'demo' else 'standard'
    PACKAGE = 'com.aqaqeer.app.demo.debug' if flavor == 'demo' else 'com.aqaqeer.app.debug'
    if not cases:
        OUTPUT.mkdir(parents=True, exist_ok=True)
        save_results(args.suite, cases, [], [])
        print('No retry methods selected for this batch; no device mutation performed.')
        return
    if os.environ.get('GITHUB_ACTIONS') != 'true' or os.environ.get('RUNNER_ENVIRONMENT') != 'github-hosted':
        raise SystemExit('This helper only runs on ephemeral GitHub-hosted runners.')
    if adb('shell', 'getprop', 'ro.kernel.qemu').stdout.strip() != b'1':
        raise SystemExit('Expected the owned emulator; refusing another device.')
    api = int(adb('shell', 'getprop', 'ro.build.version.sdk').stdout.strip())
    if args.api23 or phase != 'none':
        verify_android6_avd(35 if phase == 'peer' else 23)
    elif api == 23:
        raise SystemExit('Android 6 requires the focused offline profile.')
    elif adb('shell', 'am', 'get-current-user').stdout.strip() != b'0':
        raise SystemExit('Expected user 0 on the owned fresh AVD.')
    OUTPUT.mkdir(parents=True, exist_ok=True)
    results = []
    installations = {}
    capture_errors = []
    provenance = {'serial': SERIAL, 'package': PACKAGE, 'commit': os.environ.get('GITHUB_SHA'),
                  'suite': args.suite, 'runId': os.environ.get('GITHUB_RUN_ID'),
                  'attempt': os.environ.get('GITHUB_RUN_ATTEMPT'), 'job': os.environ.get('GITHUB_JOB'),
                  'selectedMethods': [method for _, method, _ in cases],
                  'api': str(api),
                  'user': 0, 'phase': 'APK inspection', 'apks': {}}
    save_results(args.suite, cases, results, capture_errors)
    try:
        if not cases:
            provenance['phase'] = 'no methods selected in this retry batch'
            return
        for label, pattern in (
            ('application', f'app/build/outputs/apk/{flavor}/debug/*.apk'),
            ('instrumentation', f'app/build/outputs/apk/androidTest/{flavor}/debug/*.apk'),
        ):
            provenance['phase'] = label + ': APK inspection'
            paths = list(ROOT.glob(pattern))
            if len(paths) != 1:
                raise RuntimeError(f'Expected exactly one fresh {label} APK.')
            path = paths[0]
            provenance['apks'][label] = {'path': str(path.relative_to(ROOT)),
                                       'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}
            # A new AVD must not have either package installed. No replacement/uninstall.
            package = PACKAGE if label == 'application' else PACKAGE + '.test'
            tools = build_tools()
            badging = subprocess.run([str(tools / 'aapt'), 'dump', 'badging', str(path)],
                                     capture_output=True, text=True, timeout=30, check=True).stdout
            if not badging.startswith(f"package: name='{package}' "):
                raise RuntimeError(f'Unexpected APK package for {label}')
            signer = subprocess.run([str(tools / 'apksigner'), 'verify', '--print-certs', str(path)],
                                    capture_output=True, text=True, timeout=30, check=True).stdout
            provenance['apks'][label]['signer'] = signer
            require_absent(package)
            provenance[label + 'BeforeInstall'] = 'absent on fresh owned AVD'
            (OUTPUT / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
            provenance['phase'] = label + ': installation'
            (OUTPUT / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
            adb('install', '-t', str(path), timeout=90)
            provenance['phase'] = label + ': ownership evidence'
            identity, details = installation_identity(package, observation='installed')
            installations[package] = identity
            provenance[label + 'Identity'] = identity
            provenance[label + 'Installation'] = details
            (OUTPUT / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
        for name, method, record in cases:
            provenance['phase'] = 'instrumentation: ' + method
            recorder = None
            recorder_log = None
            animation_scales = {}
            remote = f'/sdcard/aqaqeer-ci-{name}.mp4'
            try:
                large_text = method.startswith('CiPresentationUiTest#')
                adb('shell', 'settings', 'put', 'system', 'font_scale', '1.3' if large_text else '1.0')
                if method in KEYBOARD_CASES:
                    # This helper already verified its fresh, owned emulator and user above.
                    adb('shell', 'settings', 'put', 'secure', 'show_ime_with_hard_keyboard', '1')
                    if adb('shell', 'settings', 'get', 'secure', 'show_ime_with_hard_keyboard').stdout.strip() != b'1':
                        raise RuntimeError('Soft-keyboard prerequisite could not be enabled on the owned AVD.')
                    provenance['showImeWithHardKeyboard'] = '1 (read back)'
                    (OUTPUT / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
                if method == ANIMATED_SPLASH_CASE:
                    for setting in ANIMATION_SETTINGS:
                        previous = adb('shell', 'settings', 'get', 'global', setting).stdout.decode().strip()
                        if not re.fullmatch(r'null|\d+(?:\.\d+)?', previous):
                            raise RuntimeError(f'Could not read owned AVD setting {setting}.')
                        animation_scales[setting] = previous
                        adb('shell', 'settings', 'put', 'global', setting, '1.0')
                        if adb('shell', 'settings', 'get', 'global', setting).stdout.strip() != b'1.0':
                            raise RuntimeError(f'Could not set normal scale for {setting}.')
                if method in SPLASH_CASES:
                    current, _ = installation_identity(PACKAGE, observation=f'{name}-launch')
                    if current != installations[PACKAGE]:
                        raise RuntimeError('Native startup fixture no longer owns the application installation.')
                    try:
                        capture_native_startups(name, api)
                    except (OSError, RuntimeError, subprocess.SubprocessError) as error:
                        capture_errors.append(f'{name}: native startup capture incomplete: {error}')
                if record:
                    recorder_log = (OUTPUT / f'{name}-recorder.log').open('wb')
                    recorder = subprocess.Popen(
                        ['adb', '-s', SERIAL, 'shell', 'screenrecord', '--size', '360x640',
                         '--bit-rate', '1000000', '--time-limit', '45', remote],
                        stdout=recorder_log, stderr=subprocess.STDOUT,
                    )
                command = ['shell', 'am', 'instrument', '-w', '-r', '-e', 'class',
                           'com.aqaqeer.app.' + method, '-e', 'ciEvidence', 'true']
                if large_text:
                    command += ['-e', 'ciTheme', name.split('-')[0].upper()]
                if method == READER_NETWORK_CASE:
                    command += ['-e', 'ownedReaderNetworkFixture', 'true']
                if method == ANDROID6_NETWORK_CASE[1]:
                    command += ['-e', 'ownedAndroid6NetworkFixture', 'true']
                if method == EXCHANGE_CASE[1]:
                    command += ['-e', 'android6ExchangePhase', phase]
                    provenance['importedSampleSha256'] = exchange_backup(phase, api, installations, after=False)
                command += [PACKAGE + '.test/com.aqaqeer.app.SuiteRunner']
                try:
                    if method in READER_LIFECYCLE_CASES:
                        run = reader_lifecycle(command, name, method, installations[PACKAGE])
                    elif method == PIN_BOUNDARY_CASE[1]:
                        run = pin_delay_boundary(command, installations)
                    else:
                        timeout = 525 if method == READER_RETRY_CASE else (120 if flavor == 'demo' else 180)
                        run = adb(*command, timeout=timeout, check=False)
                    transcript = run.stdout + run.stderr
                    passed = instrumentation_passed(run, method)
                    status = 'passed' if passed else 'failed / incomplete instrumentation'
                except subprocess.TimeoutExpired as error:
                    transcript = (error.stdout or b'') + (error.stderr or b'')
                    status = 'timed out'
                    passed = False
                (OUTPUT / f'{name}-instrumentation.log').write_bytes(transcript)
                if passed and method == EXCHANGE_CASE[1]:
                    provenance['exportedSampleSha256'] = exchange_backup(phase, api, installations, after=True)
                results.append({'case': name, 'method': method, 'status': status,
                                'instrumentationExitCode': run.returncode if status != 'timed out' else None})
                save_results(args.suite, cases, results, capture_errors)
                if not passed:
                    try:
                        screenshot = adb('exec-out', 'screencap', '-p').stdout
                        if not screenshot.startswith(b'\x89PNG\r\n\x1a\n'):
                            raise RuntimeError('Invalid screenshot')
                        (OUTPUT / f'{name}-failure.png').write_bytes(screenshot)
                    except (OSError, RuntimeError, subprocess.SubprocessError):
                        capture_errors.append(name + ': failure screenshot unavailable')
                    try:
                        logcat = adb('logcat', '-d', '-t', '2000', timeout=20, check=False)
                        (OUTPUT / f'{name}-logcat.txt').write_bytes(logcat.stdout + logcat.stderr)
                    except (OSError, subprocess.SubprocessError):
                        capture_errors.append(name + ': logcat unavailable')
            finally:
                if recorder is not None:
                    try:
                        # Stop only the recorder whose command line contains our unique path.
                        pids = process_ids('screenrecord', api)
                        for pid in pids:
                            if pid.isdigit():
                                cmdline = adb('shell', 'cat', f'/proc/{pid}/cmdline', check=False).stdout
                                if remote.encode() in cmdline and b'screenrecord' in cmdline:
                                    adb('shell', 'kill', '-INT', pid, check=False)
                        recorder.wait(timeout=10)
                        adb('pull', remote, str(OUTPUT / f'{name}.mp4'))
                        if (OUTPUT / f'{name}.mp4').stat().st_size == 0:
                            raise RuntimeError('Empty recording')
                    except (OSError, RuntimeError, subprocess.SubprocessError):
                        capture_errors.append(name + ': recording unavailable/incomplete')
                    finally:
                        if recorder.poll() is None:
                            recorder.terminate()
                            try:
                                recorder.wait(timeout=5)
                            except subprocess.TimeoutExpired:
                                recorder.kill()
                                recorder.wait(timeout=5)
                        recorder_log.close()
                        adb('shell', 'rm', '-f', remote, check=False)
                # A timed-out instrumentation must not overlap the next case.
                current, _ = installation_identity(PACKAGE)
                if current != installations[PACKAGE]:
                    raise RuntimeError('Installation ownership changed; refusing delayed force-stop.')
                adb('shell', 'am', 'force-stop', PACKAGE)
                for setting, previous in animation_scales.items():
                    if previous == 'null':
                        adb('shell', 'settings', 'delete', 'global', setting)
                    else:
                        adb('shell', 'settings', 'put', 'global', setting, previous)
                if method == READER_NETWORK_CASE:
                    adb('shell', 'cmd', 'power', 'set-mode', '0')
                    adb('shell', 'dumpsys', 'battery', 'reset')
                    airplane = adb('shell', 'settings', 'get', 'global', 'airplane_mode_on').stdout.strip()
                    if airplane == b'1':
                        adb('shell', 'cmd', 'connectivity', 'airplane-mode', 'disable')
                    if adb('shell', 'settings', 'get', 'global', 'airplane_mode_on').stdout.strip() not in {b'0', b'null'}:
                        raise RuntimeError('Could not restore connectivity mode on the owned AVD.')
        provenance['phase'] = 'all selected invocations completed'
    except Exception as error:
        provenance['failure'] = {'type': type(error).__name__, 'message': str(error)}
        raise
    finally:
        # Assertion-time captures are made inside the live Compose activity. Keep the
        # host screenshot as a fallback for setup crashes/timeouts that bypass JUnit.
        try:
            screenshots = adb('shell', 'test', '-d', f'/sdcard/Android/data/{PACKAGE}/files/ci-visuals', check=False)
            if screenshots.returncode == 0:
                pulled = adb('pull', f'/sdcard/Android/data/{PACKAGE}/files/ci-visuals', str(OUTPUT / 'ui-screenshots'), check=False)
                if pulled.returncode != 0:
                    capture_errors.append('Assertion/success screenshots could not be pulled')
            for theme in ('light', 'dark', 'amoled'):
                case = next((item for item in results if item['case'] == theme + '-large-arabic'), None)
                if case and case['status'] == 'passed':
                    for screen in ('home', 'detail'):
                        png = OUTPUT / 'ui-screenshots' / f'{theme}-large-arabic-{screen}.png'
                        if not png.is_file() or not png.read_bytes().startswith(b'\x89PNG\r\n\x1a\n'):
                            capture_errors.append(f'{theme}: {screen} screenshot missing/invalid')
            adb('shell', 'settings', 'put', 'system', 'font_scale', '1.0', check=False)
        except (OSError, subprocess.SubprocessError):
            capture_errors.append('Final screenshot collection/font-scale cleanup incomplete')
        (OUTPUT / 'provenance.json').write_text(json.dumps(provenance, indent=2) + '\n')
        save_results(args.suite, cases, results, capture_errors)
        lines = [f'### {args.suite.title()} emulator results', '',
                 'Last phase: ' + provenance['phase'],
                 *(['Runner/setup failure: ' + provenance['failure']['message']] if 'failure' in provenance else []),
                 *[f'- {r["case"]}: {r["status"]}' for r in results],
                 *[f'- Capture limitation: {message}' for message in capture_errors], '',
                 ('Download emulator-android6 artifacts within one day.' if args.api23 else
                  f'Download {"emulator-standard-functional" if flavor == "standard" else "emulator-evidence"} artifacts within one day; GitHub storage quota can block uploads.'),
                 ('Standard cases retain instrumentation logs and failure PNG/logcat fallbacks. Splash cases also retain cold and warm launch clips.' if flavor == 'standard' else 'Clips cover at most the first 45 seconds of each UI case. ui-screenshots holds live-activity captures; host failure PNGs are post-instrumentation fallbacks.')]
        (OUTPUT / 'results.md').write_text('\n'.join(lines) + '\n')
    if len(results) != len(cases) or any(r['status'] != 'passed' for r in results) or capture_errors:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
